#!/usr/bin/env bash
# ตัดสินว่า PR ที่แตะบรรทัดไลบรารีที่ฝังไว้ (vendor) ผ่านด่านได้หรือไม่
#
# ── ทำไมโค้ดก้อนนี้ถึงถูกแยกออกมาจาก workflow ─────────────────────
# ตรรกะนี้ถูกแก้สี่รอบใน 30 ส.ค. 2026 และ **ทุกรอบเกิดรูใหม่** ที่ผู้ตรวจจับได้
#   รอบ 1  ประตูเป็นข้อความในหัว PR      -> agent เขียนหัว PR ของตัวเอง
#   รอบ 2  ประตูพิงกับ IS_AGENT          -> ไฟล์เดียวกันเขียนไว้เองว่าห้ามใช้เป็นด่านสุดท้าย
#   รอบ 3  ประตูเป็น label ที่ค้างตลอด PR -> ติดครั้งเดียว push อะไรตามมาก็ผ่านหมด
#   รอบ 4  กันเฉพาะ event synchronize    -> ไปสลับ label อื่นหรือปิดเปิด PR ก็ผ่านบน commit เดิม
# ตรรกะที่พลาดสี่รอบติดคือตรรกะที่ต้องมีเทส ไม่ใช่ตรรกะที่ต้องระวังให้มากขึ้น
# แยกออกมาเป็นสคริปต์เพื่อให้ tests/guard-rules.test.sh เรียกตัวจริงตัวนี้ได้ตรง ๆ
#
# ── กติกา ────────────────────────────────────────────────────────
# ผ่านได้ทางเดียวเท่านั้น: รอบนี้เป็นรอบที่ "เพิ่งมีคนติด label vendor-change"
# ไม่ใช่รอบที่โค้ดเพิ่งเปลี่ยน ไม่ใช่รอบที่สลับ label ตัวอื่น ไม่ใช่รอบที่ปิดแล้วเปิดใหม่
# เขียวจึงหมายถึง "มีคนตัดสินใจกับ commit ชุดนี้" เสมอ ไม่ใช่ "เคยมีคนตัดสินใจไว้ครั้งหนึ่ง"
#
# ⚠️ ยังไม่ใช่ด่านที่หัก agent ซึ่งถือ credential ของเจ้าของได้ — มันติด label เองได้เหมือนกัน
#    แต่ต้องเป็นการกระทำที่ตั้งใจแยกอีกครั้ง และเห็นในไทม์ไลน์ว่าใครติดเมื่อไหร่
#    ด่านสุดท้ายจริงคือสายตาเจ้าของ
#
# ตัวแปรที่ต้องมี: VENDORHIT IS_AGENT PR_EVENT PR_LABEL_NAME PR_AUTHOR HEAD_REF
# คืน 0 = ผ่าน · 1 = ตก

set -uo pipefail

VENDOR_LABEL='vendor-change'

vendor_gate() {
  [ "${VENDORHIT:-0}" -gt 0 ] || return 0

  if [ "${IS_AGENT:-no}" = yes ]; then
    echo "::error::PR ของ agent (โดย ${PR_AUTHOR:-?} branch ${HEAD_REF:-?}) แตะบรรทัด vendor (${VENDORHIT} บรรทัด)"
    echo "::error::  ไม่อนุญาตเด็ดขาด ต่อให้ติด label ก็ตาม — การเปลี่ยนไลบรารีเป็นเรื่องของเจ้าของ"
    return 1
  fi

  if [ "${PR_EVENT:-}" = labeled ] && [ "${PR_LABEL_NAME:-}" = "$VENDOR_LABEL" ]; then
    echo "::warning::PR นี้แตะบรรทัด vendor ${VENDORHIT} บรรทัด และเจ้าของเพิ่งติด label ${VENDOR_LABEL} ให้รอบนี้"
    echo "::warning::  ต้องอ่านด้วยตาว่าเปลี่ยนไลบรารีอะไรเป็นอะไร และขนาดไฟล์เปลี่ยนไปเท่าไหร่"
    return 0
  fi

  echo "::error::PR นี้แตะบรรทัด vendor (${VENDORHIT} บรรทัด) — ห้ามแก้ ห้าม format ดู INVARIANTS F2"
  echo "::error::  ทางออกเดียวคือให้เจ้าของ 'ติด label ${VENDOR_LABEL}' ที่ PR ใบนี้ หลังอ่าน diff ล่าสุดแล้ว"
  echo "::error::  ถ้าติดไว้อยู่แล้วให้ถอดออกแล้วติดกลับ — เขียวต้องมาจากรอบที่คนเพิ่งตัดสินใจกับ commit ชุดนี้"
  echo "::error::  ไม่ใช่ label ที่ค้างไว้จาก commit ก่อนหน้า"
  return 1
}

# ให้ source ได้โดยไม่รันทันที (ตัวเทสจะเรียก vendor_gate เอง)
if [ "${BASH_SOURCE[0]}" = "${0}" ]; then
  vendor_gate
fi
